"""Image-only patch preparation and explicit pre-outcome C7 protocol."""
from support import *
from PIL import Image
import h5py
Image.MAX_IMAGE_PIXELS=120_000_000
assert not (A/'C7A_SPEC_LOCK.json').exists(),'C7A frozen; do not regenerate scientific inputs'
for s in SAMPLES:
 with np.load(CACHE/(s+'_metadata.npz')) as f:bc=f['barcodes'];xy=f['xy_px'];mpp=float(f['mpp']);xyum=f['xy_um']
 im=Image.open(CACHE/(s+'.jpg')).convert('RGB');width=int(np.floor(112/mpp+.5));patches=[]
 for x,y in xy:
  left=int(np.floor(x-width/2+.5));top=int(np.floor(y-width/2+.5));assert 0<=left and 0<=top and left+width<=im.width and top+width<=im.height
  patches.append(np.array(im.crop((left,top,left+width,top+width)).resize((224,224),Image.Resampling.LANCZOS)))
 p=CACHE/(s+'_patches.h5')
 with h5py.File(p,'w') as f:f.create_dataset('img',data=np.stack(patches),compression='gzip');f.create_dataset('barcodes',data=np.array(bc,dtype='S'));f.create_dataset('xy_um',data=xyum)
 dump(A/'logs'/f'{s}_PATCH_AUDIT.json',{'sample_id':s,'locations':len(bc),'native_patch_pixels':width,'mpp':mpp,'FOV_um':width*mpp,'patch_hash':sha(p),'source_image_hash':sha(CACHE/(s+'.jpg')),'metadata_hash':sha(CACHE/(s+'_metadata.npz')),'no_expression_values_accessed':True})
 print(s,len(bc),mpp,width,flush=True)
audit=json.loads((A/'logs/HER2ST_METADATA_AUDIT.json').read_text())
protocol={'dataset':'HER2ST, Andersson et al. 2021, Zenodo 4751624','patients':['HER2ST_'+s[0] for s in SAMPLES],'samples':SAMPLES,'selection':'First numbered section of each of the eight source patients, fixed before reading expression values. No serial section is a separate patient. All patients included.','primary_encoder':ENC,'encoders':[ENC],'panels':audit['panel_intersections'],'minimum_primary_overlap':.8,'optional_S2_250':'not run; redundant with mandatory and secondary panels','models':['E0','E1','E2','E3'],'model_mapping':{'E0':'Frozen C4 primary D1 MLP three-seed ensemble (C5 B1)','E1':'C5 validation-selected B2a/B2b by parent panel/regime','E2':'C5 B3 with exact frozen interpolation and lambda','E3':'Secondary C5 B4 primary ResNet18 frozen heads, restricted independently by gene; same PCA and kNN6/cap250 graph'},'budgets':[.1,.2,.4],'seeds':list(range(10)),'sampling':['random','spatial_FPS'],'sampling_contract':'Nested random permutation or deterministic greedy farthest-point XY selection, start farthest from eligible centroid, ties first frozen row; exact floor(N*b+.5). No expression in sampling.','regimes':['V1','V2'],'V1':'All tissue eligible; score every unobserved location; policy changes scoring membership.','V2':'Three geometry centers at 25/50/75 percent of PC1 coordinate rank (PC1 sign first coordinate positive); nearest 40% locations form fixed unavailable region per center, tie by row; sample only outside. Score same unavailable locations at every budget/policy; all other unobserved labels hidden too.','V3':'not run','preprocessing':{'counts':'Assert finite nonnegative integer published UMI counts. log1p then exact C0 training gene mean/SD, by gene identifier. No external centering, library-size scaling, imputation, area correction, or fit.','images':'112 um nominal square using coordinate-calibrated mpp, rounded native pixel width, centered nearest integer top-left, LANCZOS resize 224 RGB, exact C0 official ResNet18 IMAGENET1K_V1 preprocessing.','coordinates':'Supplied H&E pixel centers; mpp inferred from documented 200 um array pitch and least-squares pixel vs refined array coordinate mapping. Barcode join checked.','platform_shift':'Sequencing ST 100 um diameter capture spots, 200 um pitch, versus developmental Xenium transcripts pooled in 100 um squares. Counts are both per-location nonnegative integers with the same frozen log-count model interface; capture efficiency/area/depth differs. This is a cross-platform zero-shot test, not a same-assay calibration claim.','source_QC':'Published selected spots and gene columns inherit source filtering. Shared intersection frozen using gene headers only. Upstream tissue/gene filtering is not refit here.'},'distance_bin_edges_um':[0,150,300,600,1200,2400,None],'correlation_minimum_bin_locations':20,'figure_genes':audit['panel_intersections']['S2-50'][:6],'negative_controls':{'sample':'A1','budget':.2,'seed':0,'regimes':{'V1':0,'V2':1},'strategies':['random'],'models':['E1','E2','E3'],'controls':['NC1','NC2','NC3'],'control_seeds':[0,1,2]},'pass_criteria':{'unit':'patient; masks/seeds averaged within patient/budget/regime/policy before patient summaries','meaningful_E2_over_E0':'delta median Pearson >=0.02 AND relative mean MSE reduction >=0.02','meaningful_E2_over_E1':'delta median Pearson >=0.01 AND relative mean MSE reduction >=0.01','primary':'S2-50 common 40-gene intersection; V1 random is primary, regular and V2 separately reported','pass':'At least 6/8 patients show meaningful E2>E0 at >=2/3 V1-random budgets, and >=4/8 show meaningful E2>E1 at >=1 budget; positive median patient gains over both; <=25% V1-random settings with E2 MSE > E1 by >2%; >=6/8 patients have E2 Pearson(40%)>Pearson(10%) and MSE(40%)<MSE(10%); distance behavior characterized, V2 honestly reported, all audits pass.','limited':'Same interpolation criteria but external evidence limited by assay, panel, patient count, or non-replicating contiguous regime; report qualification/domain limitations explicitly.','mixed':'Does not pass; at least 2 patients meet meaningful E2>E0 at one V1-random budget or E2>E1 at one; otherwise FAIL_EXTERNAL_VALIDATION.','technical':'Any corrupted hidden-label dependence, replay mismatch, parent hash change, noninteger/incompatible target representation, or identity failure => FAIL_TECHNICAL.','V2_support':'Report separately: >=4/8 patients show E2>E0 meaningful at >=1 random budget and >=4/8 E2>E1 at >=1 budget. Does not rescue failed V1.'},'adaptation':'not run','C7C':'not run; independent breast cohort already tests platform shift as primary','external_evaluation_authorized':False}
dump(OUT/'configs/protocol.json',protocol)
